static int cow_read_master(CLIENT *client, off_t a, char *buf, size_t len) {
	while(len > 0) {
		int fhandle;
		off_t foffset;
		size_t maxbytes;
		size_t chunk = len;
		ssize_t ret;

		if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
