			chunk = DIFFPAGESIZE - blockoff;
		if(client->difmap[block]) {
			off_t diffoff = (client->difmap[block] - 1) * DIFFPAGESIZE + blockoff;
			DEBUG("(COW READ from fd %d offset %llu len %zu), ", client->difffile, (unsigned long long)diffoff, chunk);
			if(pread(client->difffile, buf + done, chunk, diffoff) != (ssize_t)chunk)
				return -1;
		} else {
			DEBUG("(COW READ from master offset %llu len %zu), ", (unsigned long long)pos, chunk);
			if(cow_read_master(client, pos, buf + done, chunk))
				return -1;
		}
		done += chunk;
	}
