/**
 * Write an amount of bytes at a given offset to the diff file of a
 * copy-on-write export. The master file is left alone.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
ssize_t rawexpwrite_cow(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	size_t done = 0;

	while(done < len) {
		off_t pos = a + done;
		uint64_t block = pos / DIFFPAGESIZE;
		size_t blockoff = pos % DIFFPAGESIZE;
		size_t chunk = len - done;

		if(chunk > DIFFPAGESIZE - blockoff)
			chunk = DIFFPAGESIZE - blockoff;
		DEBUG("(COW WRITE to fd %d block %llu offset %zu len %zu fua %d), ", client->difffile, (unsigned long long)block, blockoff, chunk, fua);
		if(cow_write_block(client, block, blockoff, buf + done, chunk))
			return -1;
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if (fua) {
		fdatasync(client->difffile);
	}
	return len;
}

/**
 * Read an amount of bytes at a given offset from the diff file of a
 * copy-on-write export. Blocks which the client has written during
 * this connection are read back from the diff file, everything else
 * is read from the master file.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
ssize_t rawexpread_cow(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t done = 0;

	while(done < len) {
		off_t pos = a + done;
		uint64_t block = pos / DIFFPAGESIZE;
		size_t blockoff = pos % DIFFPAGESIZE;
		size_t chunk = len - done;

		if(chunk > DIFFPAGESIZE - blockoff)
			chunk = DIFFPAGESIZE - blockoff;
		if(client->difmap[block]) {
			off_t diffoff = (client->difmap[block] - 1) * DIFFPAGESIZE + blockoff;
			DEBUG("(COW READ from fd %d offset %llu len %zu), ", client->difffile, (unsigned long long)diffoff, chunk);
			if(pread(client->difffile, buf + done, chunk, diffoff) != (ssize_t)chunk)
				return -1;
		} else {
			DEBUG("(COW READ from master offset %llu len %zu), ", (unsigned long long)pos, chunk);
			if(cow_read_master(client, pos, buf + done, chunk))
				return -1;
		}
		done += chunk;
	}
	return done;
}

