 * Write data to the copy-on-write diff file.
 *
 * Data is handled in DIFFPAGESIZE-sized blocks. A block which the
 * client writes to for the first time is allocated in the diff file:
 * when sparse_cow is in effect it gets its natural position, so the
 * diff file is a sparse copy of the export; otherwise it is appended
 * to the end of the diff file, and lseek()ing is needed to find it
 * back. Blocks which are only partially covered by a write are
 * completed with their current contents (from the diff file if the
 * block was written before, from the master file otherwise) before
 * being written to the diff file.
 *
 * @param client The client we're serving for
 * @param block The block number (in the export) the data belongs to
 * @param blockoff The offset within the block where the data starts
 * @param buf The buffer to write from
 * @param len The length of buf, at most DIFFPAGESIZE - blockoff
 * @return 0 on success, -1 in case of an error
 **/
static int cow_write_block(CLIENT *client, uint64_t block, size_t blockoff,
		const char *buf, size_t len) {
	bool dirty = client->difmap[block] != 0;
	off_t diffoff;

	if(!dirty) {
		off_t pos;
		if(client->server->flags & F_SPARSE) {
			pos = (off_t)block * DIFFPAGESIZE;
		} else {
			pos = client->difffilelen;
			client->difffilelen += DIFFPAGESIZE;
		}
		client->difmap[block] = pos / DIFFPAGESIZE + 1;
	}
	diffoff = (client->difmap[block] - 1) * DIFFPAGESIZE;

	if(len < DIFFPAGESIZE) {
		char tmp[DIFFPAGESIZE];
		off_t start = (off_t)block * DIFFPAGESIZE;
		size_t avail = DIFFPAGESIZE;

		/* the last block of an export may be shorter than
		 * DIFFPAGESIZE */
		if((uint64_t)start + avail > client->exportsize)
			avail = client->exportsize - start;
		memset(tmp, 0, sizeof(tmp));
		if(dirty) {
			if(pread(client->difffile, tmp, avail, diffoff) != (ssize_t)avail)
				return -1;
		} else {
			if(cow_read_master(client, start, tmp, avail))
				return -1;
		}
		memcpy(tmp + blockoff, buf, len);
		if(pwrite(client->difffile, tmp, DIFFPAGESIZE, diffoff) != DIFFPAGESIZE)
			return -1;
		return 0;
	}
	if(pwrite(client->difffile, buf, DIFFPAGESIZE, diffoff) != DIFFPAGESIZE)
		return -1;
	return 0;
}

/**
 * Write an amount of bytes at a given offset to the diff file of a
 * copy-on-write export. The master file is left alone.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
ssize_t rawexpwrite_cow(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	size_t done = 0;
	ssize_t retval;

	/* the diff file and the block map are shared state; serialize
	 * writers */
	pthread_rwlock_wrlock(&client->export_lock);
	while(done < len) {
		off_t pos = a + done;
		uint64_t block = pos / DIFFPAGESIZE;
		size_t blockoff = pos % DIFFPAGESIZE;
		size_t chunk = len - done;

		if(chunk > DIFFPAGESIZE - blockoff)
			chunk = DIFFPAGESIZE - blockoff;
		DEBUG("(COW WRITE to fd %d block %llu offset %zu len %zu fua %d), ", client->difffile, (unsigned long long)block, blockoff, chunk, fua);
		if(cow_write_block(client, block, blockoff, buf + done, chunk)) {
			retval = -1;
			goto out;
		}
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if (fua) {
		fdatasync(client->difffile);
	}
	retval = len;
out:
	pthread_rwlock_unlock(&client->export_lock);
	return retval;
}

